  /** The columns of the people list this screen can switch off. */
  protected readonly columns = PEOPLE_COLUMNS;

  /** The sheet's grades, in order: the standing ones, then those added. */
  protected readonly grades = this.session.grades;
  protected readonly people = signal<Person[]>([]);
  /** The dates of the last snapshot comparison asked for; to is blank for now; null until one is asked. */
  private readonly snapshotDates = signal<{ from: string; to: string } | null>(null);
  /**
   * Per person on screen, in list order: their due-total in the SNAPSHOT written when the sheet's today
   * was changed away from the from-date, and in the one for the to-date (their due-total now when the
   * to-date is blank); blank when no such snapshot was written, the last one written when several were.
   */
  protected readonly snapshotComparison = computed(() => {
    const dates = this.snapshotDates();
    if (dates === null) return [];
    const on = (p: Person, day: string): string => {
      const found = p.snapshots.filter((s) => s.day === day).at(-1);
      return found === undefined ? '' : (found.dueTotal ?? NA);
    };
    return this.sorted().map((p) => ({
      name: p.name,
      then: on(p, dates.from),
      now: dates.to === '' ? this.dueTotalOf(p) : on(p, dates.to),
    }));
  });
  /** The sheet's descendants' figures, as the store held them when the sheet was loaded (as of the user's date, while one is set). */
  private readonly descendants = signal<Descendants | null>(null);
  /**
   * The sheet's own figures, as shown, and its descendants' added up. Read as of a date, every sheet of the
   * tree is as it stood at the end of that date.
   */
  protected readonly consolidated = computed(() => {
    const d = this.descendants();
    const others = d?.personFigures ?? [];
    const key = (name: string) => name.trim().toLowerCase();
    const dues = this.people().map((p) => this.dueTotalCents(p)).filter((c): c is number => c !== null)
      .concat(others.filter((o) => o.dueTotal !== null).map((o) => cents(o.dueTotal as string)));
    const overdues = [...this.overdueByPerson().values()].map((o) => o.cents)
      .concat(others.map((o) => cents(o.overdueTotal)));
    return {
      // each person once over the tree, the trim over every person's figure of the tree
      people: distinctPeople(this.people().map((p) => [key(p.name), ...p.aliases.map(key)])
        .concat(others.map((o) => o.keys))),
      dueCents: trimmedSum(dues),
      overdueCents: trimmedSum(overdues),
      grades: this.gradeSummary().map((g) => ({
        grade: g.grade,
        dueCents: cents(g.dueTotal) + cents(d?.gradeDueTotals?.[g.grade] ?? '0.00'),
      })),
      statuses: this.statusSummary().map((s) => ({ status: s.status, count: s.count + (d?.statusCounts?.[s.status] ?? 0) })),
    };
  });
  /**
   * The people a restricted user may see: the person with their name and the people of the crews that
   * person leads or belongs to, and anyone they added on this screen since the sheet was loaded; null for
   * any other role (everyone).
   */
  private readonly visibleIds = computed<ReadonlySet<number> | null>(() => {
    if (this.session.role() !== 'restricted') return null;
    const user = this.session.user()?.trim();
    const floor = this.session.floorCentsOn;
    const late = this.session.late();
    const given = this.shareParts().given;
    const by = new Map<number, Split>();
    for (const p of this.people()) {
      const pctOn = this.pctOnOf(p.id);
      const graceOn = this.graceOnOf(p.id);
      const theirs = this.claimsOf(p.id);
      const split: Split = { settled: 0, open: 0, scored: 0 };
      for (const c of theirs) {
        if (!this.counts(c)) continue;
        const due = claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs), graceOn) ?? 0;
        const own = due - (given.get(c.id) ?? 0);
        if (c.status === 'SETTLED') split.settled += own;
        else split.open += own;
        if (c.status === 'SETTLED' && c.corrects === null) split.scored += due;
      }
      for (const h of this.heldPartsOf(p.id)) {
        if (h.claim.status === 'SETTLED') split.settled += h.cents;
        else split.open += h.cents;
      }
      by.set(p.id, split);
    }
    return by;
  });
  /** The sheet's settled-total and open-total: everyone's added up, not trimmed. */
  protected readonly splitTotal = computed(() => {
    const total: Split = { settled: 0, open: 0, scored: 0 };
    for (const s of this.splitByPerson().values()) {
      total.settled += s.settled;
      total.open += s.open;
      total.scored += s.scored;
    }
    return total;
  });
  /** The sheet's age buckets in cents: everyone's added up, not trimmed. */
  protected readonly agedTotal = computed(() => {
    const total: Aged = { upTo30: 0, upTo60: 0, over60: 0 };
    for (const a of this.agedByPerson().values()) {
      total.upTo30 += a.upTo30;
      total.upTo60 += a.upTo60;
      total.over60 += a.over60;
    }
    return total;
  });
  /** The sheet's cut total in cents: everyone's cut totals added up. */
  protected readonly cutTotal = computed(() =>
    this.people().reduce((sum, p) => sum + this.cutTotalOf(p.id), 0));
  /** The sheet's overdue claims that count: everyone's added up. */
  protected readonly overdueTotal = computed(() => {
    let count = 0;
    for (const o of this.overdueByPerson().values()) count += o.count;
    return { count, cents: trimmedSum([...this.overdueByPerson().values()].map((o) => o.cents)) };
  });
  /** Per grade: the people not retired on it today, their due-totals added up, skipping n/a, and how many are active. */
  protected readonly gradeSummary = computed(() =>
    this.grades().map((grade) => {
      const on = this.people().filter((p) => !p.retired && this.gradeOf(p) === grade);
      return { grade, count: on.length, dueTotal: money(on.reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0)),
        active: on.filter((p) => p.active).length };
    }),
